 dirs=[(dr,dc) for dr in [-1,0,1] for dc in [-1,0,1] if (dr or dc) and (diag or dr==0 or dc==0)]
 for r,c in zip(*np.where(mask)):
  if (r,c) in seen: continue
  q=[(int(r),int(c))]; seen.add((int(r),int(c))); comp=[]
  while q:
   a,b=q.pop(); comp.append((a,b))
   for dr,dc in dirs:
    x,y=a+dr,b+dc
    if 0<=x<mask.shape[0] and 0<=y<mask.shape[1] and mask[x,y] and (x,y) not in seen: seen.add((x,y));q.append((x,y))
  arr.append(comp)
 return sorted(arr,key=len,reverse=True)
